package az.iktex.organization.structure.testders.repository;
import az.iktex.organization.structure.testders.entity.Department; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface DepartmentRepository extends JpaRepository<Department,Long> { boolean existsByName(String name); boolean existsByNameAndIdNot(String name,Long id); @Query("select d from Department d where d.employees is empty") List<Department> findWithoutEmployees(); @Query("select d from Department d left join fetch d.employees where d.id=:id") Optional<Department> findDetailById(@Param("id") Long id); @Query("select case when count(e)>0 then true else false end from Employee e where e.department.id=:id") boolean hasEmployees(@Param("id") Long id); }